function resolveAfter(t){return Promise.resolve(t)}async function sequence(){print("start");const t=await resolveAfter(1);print("got a="+t);const e=await resolveAfter(t+10);print("got b="+e);const r=await resolveAfter(t+e);return print("got c="+r),t+e+r}sequence().then(function(t){print("total="+t)}),print("sync code after call runs first");